-- M4 standard quotation foundation; cc_* only.
CREATE TABLE IF NOT EXISTS cc_quotes (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,quote_no VARCHAR(80) NOT NULL,legacy_customer_id BIGINT UNSIGNED NULL,customer_snapshot LONGTEXT NULL,quote_type VARCHAR(30) NOT NULL DEFAULT 'standard',currency CHAR(3) NOT NULL DEFAULT 'USD',language VARCHAR(10) NOT NULL DEFAULT 'en',current_version INT UNSIGNED NOT NULL DEFAULT 1,status VARCHAR(30) NOT NULL DEFAULT 'draft',total_amount DECIMAL(18,4) NOT NULL DEFAULT 0,total_cost DECIMAL(18,4) NOT NULL DEFAULT 0,is_test TINYINT(1) NOT NULL DEFAULT 0,created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_quote_no(quote_no),KEY idx_cc_quote_status(status,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_quote_versions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,quote_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,customer_snapshot LONGTEXT NULL,terms_snapshot LONGTEXT NULL,pricing_snapshot LONGTEXT NULL,cost_snapshot LONGTEXT NULL,exchange_rate DECIMAL(18,8) NOT NULL DEFAULT 1,template_version VARCHAR(40) NOT NULL DEFAULT 'legacy_v1',status VARCHAR(30) NOT NULL DEFAULT 'draft',created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_quote_version(quote_id,version_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_quote_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,quote_version_id BIGINT UNSIGNED NOT NULL,item_type VARCHAR(30) NOT NULL,legacy_product_id BIGINT UNSIGNED NULL,inventory_sku_id BIGINT UNSIGNED NULL,description VARCHAR(500) NOT NULL,configuration_snapshot LONGTEXT NULL,quantity DECIMAL(18,3) NOT NULL,unit_price DECIMAL(18,4) NOT NULL,cost_amount DECIMAL(18,4) NOT NULL DEFAULT 0,discount_rate DECIMAL(9,4) NOT NULL DEFAULT 0,line_amount DECIMAL(18,4) NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),KEY idx_cc_quote_item_version(quote_version_id,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_quote_item_snapshots (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,quote_item_id BIGINT UNSIGNED NOT NULL,product_snapshot LONGTEXT NOT NULL,configuration_snapshot LONGTEXT NULL,price_snapshot LONGTEXT NOT NULL,cost_snapshot LONGTEXT NULL,snapshot_hash CHAR(64) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_quote_item_snapshot(quote_item_id,snapshot_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
